begin;

update public.spell_catalog set name_ru='Провокация', effect_summary='Одно существо в пределах 30 футов делает спасбросок Мудрости. При провале получает 4к4 психического урона и немедленно тратит реакцию на рукопашную атаку по другому выбранному тобой существу, которое ты видишь. Если атаковать невозможно, следующая атака цели до начала твоего следующего хода совершается с помехой. При успехе — половина урона без дополнительного эффекта.', author_description='Ты буквально доводишь цель до состояния «ударь кого-нибудь прямо сейчас». В плотной вражеской группе это превращает одного противника в кратковременную проблему для другого.', author_comment='Магическая версия фразы «а он про тебя что сказал?» — только с психическим уроном.', upcast='Урон увеличивается на 1к4 за каждый уровень ячейки выше 3.', notes='Для вынужденной атаки у цели должна быть доступна реакция и подходящее существо в досягаемости.', casting_time='1 действие' where slug='antagonize' and source_kind='official';

update public.spell_catalog set name_ru='Шаг Ашардалона', effect_summary='Бонусным действием окутываешь ноги драконьим пламенем на срок до 1 минуты с концентрацией. Скорость увеличивается на 20 футов, твоё перемещение не провоцирует атаки, а когда впервые за ход проходишь в пределах 5 футов от существа или предмета, оно получает 1к6 огненного урона без броска атаки и спасброска.', author_description='Ты перестаёшь быть персонажем и становишься бегущей полосой пожара. Чем больше врагов удаётся обежать за ход, тем веселее геометрия.', author_comment='Заклинание для тех, кто всегда хотел наносить урон самим фактом прохождения мимо.', upcast='За каждый уровень ячейки выше 3 урон увеличивается на 1к6, а бонус к скорости — ещё на 5 футов.', notes='Одно и то же существо или предмет получает этот урон не более одного раза за ход. Требуется концентрация.', casting_time='1 бонусное действие' where slug='ashardalon-s-stride' and source_kind='official';

update public.spell_catalog set name_ru='Какофонический щит', effect_summary='На срок до 10 минут с концентрацией вокруг тебя действует 10-футовая звуковая эманация. Существо, вошедшее в неё, оказавшееся в ней из-за твоего движения или закончившее там ход, делает спасбросок Телосложения: при провале получает 3к6 звукового урона и глохнет до начала твоего следующего хода, при успехе — половину урона. Ты получаешь сопротивление звуковому урону, а дальнобойные атаки по тебе совершаются с помехой.', author_description='Ходячая стена отвратительного шума: врагам больно подходить, стрелять неудобно, а тебе внезапно меньше страшен чужой гром.', author_comment='Защита, построенная на принципе «если достаточно громко, никто не захочет подходить».', upcast='Урон увеличивается на 1к6 за каждый уровень ячейки выше 3.', notes='При сотворении можно назначить существ, которых эманация не затрагивает. Одно существо делает этот спасбросок не более одного раза за ход.', casting_time='1 действие' where slug='cacophonic-shield' and source_kind='official';

update public.spell_catalog set name_ru='Короткий сон', effect_summary='До трёх добровольных существ в пределах 30 футов засыпают и становятся Бессознательными на 10 минут. Если сон не прерывается, после пробуждения они получают все преимущества короткого отдыха. Получив урон или если кто-то действием разбудит цель, она просыпается раньше и преимуществ отдыха не получает.', author_description='Магически превращаешь десять минут в полноценный короткий отдых. Иногда это буквально самое продуктивное совещание группы за день.', author_comment='Сон на работе наконец становится тактической механикой.', upcast='За каждый уровень ячейки выше 3 можно выбрать ещё одно существо.', notes='Существа, невосприимчивые к магическому сну, не подвержены заклинанию. После успешного короткого отдыха от этого заклинания существо нельзя снова так усыпить до окончания долгого отдыха.', casting_time='1 действие' where slug='catnap' and source_kind='official';

update public.spell_catalog set name_ru='Призыв конструктов', effect_summary='Призываешь в свободное пространство в пределах 60 футов группу нематериальных духов-конструктов на срок до 10 минут с концентрацией. При сотворении и действием в последующие ходы можно приказать им воздействовать на цель рядом с ними: либо спасбросок Ловкости и 3к6 силового урона при провале, либо 1к6 + модификатор заклинательной характеристики временных хитов. Когда ты двигаешься, духов можно переместить до 30 футов.', author_description='Маленький отряд модронов или других конструктов, который умеет либо бить по расписанию, либо выдавать временную броню. Очень организованная магия.', author_comment='Даже призванные духи-конструкты знают, что работа делится на «сломать» и «починить».', upcast='За каждый уровень ячейки выше 3 урон и количество выдаваемых временных хитов увеличиваются на 1к6.', notes='Требуется концентрация. Духи нематериальны; эффект выбирается каждый раз при команде.', casting_time='1 действие' where slug='conjure-constructs' and source_kind='official';

update public.spell_catalog set name_ru='Враги повсюду', effect_summary='Одно существо в пределах 120 футов делает спасбросок Интеллекта. При провале до 1 минуты с концентрацией оно перестаёт различать друзей и врагов. Когда выбирает цель для атаки, заклинания или способности, оно случайно определяет подходящую цель среди видимых существ; если рядом кто-то провоцирует атаку, цель должна её совершить, если способна. При получении урона повторяет спасбросок.', author_description='Ты не заставляешь цель видеть чудовищ — просто убираешь из её головы категорию «союзник». Дальше бой сам становится значительно интереснее.', author_comment='Когда все вокруг враги, командная работа становится статистической ошибкой.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Существа, невосприимчивые к Испугу, также невосприимчивы к этому заклинанию. Получение урона даёт повторный спасбросок Интеллекта.', casting_time='1 действие' where slug='enemies-abound' and source_kind='official';

update public.spell_catalog set name_ru='Извержение земли', effect_summary='В точке в пределах 120 футов взрывается куб земли размером 20 футов. Существа в области делают спасбросок Ловкости, получая 3к12 дробящего урона при провале или половину при успехе. После взрыва земля в области становится труднопроходимой, пока её не расчистят.', author_description='Земля внезапно решает стать снарядом. После урона она ещё и оставляет после себя поле, по которому врагам неудобно идти.', author_comment='Огненный шар оставляет дым. Это оставляет ремонтные работы.', upcast='Урон увеличивается на 1к12 за каждый уровень ячейки выше 3.', notes='Каждый квадрат труднопроходимой земли размером 5 футов можно расчистить вручную примерно за 1 минуту.', casting_time='1 действие' where slug='erupting-earth' and source_kind='official';

update public.spell_catalog set name_ru='Быстрые друзья', effect_summary='Выбираешь гуманоида в пределах 30 футов, который видит, слышит и понимает тебя. При провале спасброска Мудрости он Очарован тобой до 1 часа с концентрацией и дружелюбно выполняет порученные услуги и задачи. Опасное или противоречащее его желаниям поручение даёт новый спасбросок; приказ, означающий неминуемую смерть, прекращает заклинание.', author_description='Очень эффективный способ завести друга, который потом совершенно точно захочет обсудить обстоятельства вашего знакомства.', author_comment='Название честное только наполовину: друзья появляются быстро, последствия — чуть позже.', upcast='За каждый уровень ячейки выше 3 можно выбрать ещё одного гуманоида.', notes='Если ты или союзники сражаются с целью, повторный спасбросок против опасного задания совершается с преимуществом. После окончания цель знает, что была очарована.', casting_time='1 действие' where slug='fast-friends' and source_kind='official';

update public.spell_catalog set name_ru='Пламенные стрелы', effect_summary='Касаешься колчана со стрелами или болтами. Следующие 12 боеприпасов, извлечённые из него во время концентрации до 1 часа, при попадании дополнительно наносят 1к6 огненного урона. После попадания магия на конкретном снаряде исчезает.', author_description='Ты не зачаровываешь лучника — ты превращаешь его колчан в двенадцать маленьких обещаний пожара.', author_comment='Двенадцать стрел. Двенадцать шансов объяснить врагу, почему дерево и огонь плохо сочетаются.', upcast='За каждый уровень ячейки выше 3 заклинание зачаровывает ещё 2 боеприпаса.', notes='Заклинание заканчивается, когда использованы все зачарованные боеприпасы, либо прекращается концентрация.', casting_time='1 действие' where slug='flame-arrows' and source_kind='official';

update public.spell_catalog set name_ru='Башня Гальдера', effect_summary='За 10 минут создаёшь на 24 часа двухэтажную башню из прочного материала. Каждый этаж высотой 10 футов и площадью до 100 квадратных футов; для каждого выбираешь назначение — спальня, кабинет, столовая, гостиная, уборная/баня, обсерватория или пустая комната. Внутри тепло и сухо независимо от погоды.', author_description='Магия для человека, который посмотрел на походную палатку и сказал: «нет, у меня есть стандарты».', author_comment='Когда волшебник обещает «быстро поставить лагерь», иногда он имеет в виду недвижимость.', upcast='За каждый уровень ячейки выше 3 башня получает ещё один этаж. Ежедневное сотворение в одном месте и одной конфигурации в течение года делает башню постоянной.', notes='Предметы обстановки, созданные заклинанием, исчезают при выносе наружу. После окончания чужие существа и предметы безопасно оказываются снаружи.', casting_time='10 минут' where slug='galder-s-tower' and source_kind='official';

update public.spell_catalog set name_ru='Разжигание алчности', effect_summary='Демонстрируешь драгоценный камень и выбираешь существ в пределах 30 футов, которые видят тебя. При провале спасброска Мудрости цель Очарована на срок до 1 минуты с концентрацией: в свой ход она должна двигаться к тебе максимально безопасным путём и, оказавшись в пределах 5 футов, не делает ничего, кроме как жадно смотреть на камень. В конце каждого хода повторяет спасбросок.', author_description='Иногда самый надёжный контроль толпы — просто показать очень дорогую вещь и магически усилить плохие финансовые решения окружающих.', author_comment='Драгоценный камень наконец получает то внимание, которого всегда заслуживал.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется драгоценный камень стоимостью не менее 50 зм; он не расходуется. Получение урона может дать цели дополнительный шанс вырваться из эффекта.', casting_time='1 действие' where slug='incite-greed' and source_kind='official';

update public.spell_catalog set name_ru='Крепость интеллекта', effect_summary='Одно добровольное существо в пределах 30 футов на срок до 1 часа с концентрацией получает сопротивление психическому урону и преимущество на спасброски Интеллекта, Мудрости и Харизмы.', author_description='Персональный магический фаервол для мозга. Полезен против чар, страха, телепатии и всего, что считает разум удобной точкой входа.', author_comment='Если враг атакует мысли, пора поставить на них пароль.', upcast='За каждый уровень ячейки выше 3 можно выбрать ещё одно существо.', notes='Требуется концентрация. Все выбранные цели должны быть добровольными.', casting_time='1 действие' where slug='intellect-fortress' and source_kind='official';

update public.spell_catalog set name_ru='Серебряное копьё Лаэраль', effect_summary='Из тебя вырывается линия серебряной силы длиной 120 футов и шириной 5 футов. Выбранные тобой существа в линии делают спасбросок Силы: при провале получают 3к10 урона силовым полем и падают ничком, при успехе получают половину урона без падения.', author_description='Очень длинное энергетическое копьё, которое одновременно пробивает строй и буквально валит его на землю.', author_comment='Сто двадцать футов — это уже не копьё. Это аргумент в форме коридора.', upcast='Урон увеличивается на 1к10 за каждый уровень ячейки выше 3.', notes='Материальный компонент — серебряная булавка стоимостью 250+ зм; она не расходуется. Ты выбираешь, какие существа в линии затрагиваются.', casting_time='1 действие' where slug='laeral-s-silver-lance' and source_kind='official';

update public.spell_catalog set name_ru='Передача жизни', effect_summary='Ты получаешь 4к8 некротического урона, который нельзя уменьшить никаким способом, после чего одно существо в пределах 30 футов восстанавливает хиты в количестве, равном удвоенному полученному тобой урону.', author_description='Очень прямой обмен: твоё здоровье превращается в чужое, причём с хорошим курсом. Полезно, если союзник умирает быстрее, чем ты.', author_comment='Магическая медицина, где донор действительно чувствует каждую монету счёта.', upcast='Твой получаемый урон увеличивается на 1к8 за каждый уровень ячейки выше 3, соответственно растёт и лечение цели.', notes='Урон заклинателю нельзя предотвратить или уменьшить сопротивлением, иммунитетом и другими эффектами.', casting_time='1 действие' where slug='life-transference' and source_kind='official';

update public.spell_catalog set name_ru='Связанные глифы', effect_summary='За 1 час создаёшь глиф-датчик и связанный с ним глиф эффекта. Датчик можно настроить на условие срабатывания; он почти невидим и ломается, если его основу сдвинуть более чем на 10 футов. Связанный глиф может либо послать тебе мысленный сигнал, либо хранить подготовленное заклинание до 4 уровня и автоматически сотворить его при срабатывании датчика.', author_description='Это «Символ защиты», у которого датчик и полезная часть могут находиться в разных местах. Получается полноценная магическая сигнализация, ловушка или удалённый триггер.', author_comment='Наконец-то магическая система умного дома с ценой установки 300 золотых.', upcast='Если создаёшь глиф заклинания ячейкой 5 уровня или выше, можно сохранить заклинание вплоть до уровня использованной ячейки.', notes='Требуются благовония и алмазная пыль стоимостью 300+ зм, которые расходуются. Для глифа заклинания связанные глифы должны быть в пределах 100 футов друг от друга; сохранённое заклинание действует с полной длительностью даже если обычно требует концентрации.', casting_time='1 час' where slug='linked-glyphs' and source_kind='official';

update public.spell_catalog set name_ru='Малые метеоры Мелфа', effect_summary='Создаёшь шесть маленьких огненных метеоров, вращающихся вокруг тебя до 10 минут с концентрацией. Бонусным действием можешь запустить один или два в точки в пределах 120 футов; каждый взрывается в радиусе 5 футов, заставляя существ пройти спасбросок Ловкости и нанося 2к6 огненного урона при провале или половину при успехе.', author_description='Запасаешь шесть мини-взрывов заранее и потом выдаёшь их по одному или по два бонусным действием. Хорошая магическая батарея для длинного боя.', author_comment='Огненный шар слишком большой? Мелф придумал упаковку по шесть штук.', upcast='За каждый уровень ячейки выше 3 создаётся ещё 2 метеора.', notes='Требуется концентрация. Неиспользованные метеоры исчезают при окончании заклинания.', casting_time='1 действие' where slug='melf-s-minute-meteors' and source_kind='official';

update public.spell_catalog set name_ru='Мотивационная речь', effect_summary='До пяти существ в пределах 60 футов, которые слышат тебя, на 1 час получают 5 временных хитов и преимущество на спасброски Мудрости. Когда затронутое существо получает попадание атакой, его следующая атака совершается с преимуществом; после потери временных хитов, выданных этим заклинанием, эффект для него заканчивается.', author_description='Ты говоришь минуту настолько убедительно, что группа временно становится смелее, крепче и агрессивнее после первого удара.', author_comment='Корпоративный тренинг, который почему-то действительно даёт временные хиты.', upcast='Временные хиты увеличиваются на 5 за каждый уровень ячейки выше 3.', notes='Существо должно слышать тебя. Преимущество на атаку возникает после попадания по нему и относится к следующей атаке.', casting_time='1 минута' where slug='motivational-speech' and source_kind='official';

update public.spell_catalog set name_ru='Импульсная волна', effect_summary='Выпускаешь 30-футовый конус гравитационной силы. Существа в нём делают спасбросок Телосложения, получая 6к6 силового урона при провале или половину при успехе. Провалившую цель ты также либо притягиваешь к себе, либо отталкиваешь от себя на расстояние до 15 футов.', author_description='Хороший урон плюс бесплатное редактирование расстановки врагов. Можно расчистить проход или, наоборот, собрать цель ближе к группе.', author_comment='Гравитация обычно знает только направление вниз. Здесь у неё появляется выбор.', upcast='Урон увеличивается на 1к6 за каждый уровень ячейки выше 3.', notes='Перемещение применяется только при проваленном спасброске; направление выбираешь ты отдельно для каждой цели.', casting_time='1 действие' where slug='pulse-wave' and source_kind='official';

update public.spell_catalog set name_ru='Духовный покров', effect_summary='Бонусным действием окружаешь себя духами на срок до 1 минуты с концентрацией. Пока заклинание действует, твои атаки по существам в пределах 10 футов наносят дополнительно 1к8 урона выбранного при сотворении типа: холодом, некротического или излучением. Получившая этот урон цель не может восстанавливать хиты до начала твоего следующего хода, а выбранные тобой существа, начинающие ход в 10 футах от тебя, теряют 10 футов скорости до начала твоего следующего хода.', author_description='Ближний бой становится заметно неприятнее для всех вокруг: дополнительный урон, запрет лечения и немного замедления в одном пакете.', author_comment='Духи мёртвых пришли помочь. Их представление о помощи довольно агрессивное.', upcast='Дополнительный урон увеличивается на 1к8 за каждые два уровня ячейки выше 3: 2к8 ячейкой 5, 3к8 ячейкой 7 и 4к8 ячейкой 9.', notes='Тип дополнительного урона выбирается при сотворении. Требуется концентрация.', casting_time='1 бонусное действие' where slug='spirit-shroud' and source_kind='official';

update public.spell_catalog set name_ru='Призыв феи', effect_summary='Призываешь фейский дух в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь настроение духа — яростное, весёлое или проказливое — которое меняет его особое действие после телепортации. Дух действует сразу после тебя и выполняет команды.', author_description='Одна фея, три режима поведения: боец, очаровашка или специалист по неприятным трюкам. Настроение выбирается при вызове, поэтому лучше решить заранее, какой хаос сегодня нужен.', author_comment='Фея с переключателем настроения — всё равно фея. Просто теперь хаос документирован в статблоке.', upcast='При использовании ячейки выше 3 уровень ячейки используется в характеристиках фейского духа, усиливая его статблок.', notes='Требуется концентрация. Материальный фокус — позолоченный цветок стоимостью 300+ зм; он не расходуется.', casting_time='1 действие' where slug='summon-fey' and source_kind='official';

update public.spell_catalog set name_ru='Призыв малых демонов', effect_summary='Призываешь группу демонов в свободные пространства в пределах 60 футов на срок до 1 часа с концентрацией. Бросок к6 определяет число и максимальную опасность призванных существ: 1–2 — два демона ПО 1 или ниже; 3–4 — четыре ПО 1/2 или ниже; 5–6 — восемь ПО 1/4 или ниже. Демонов выбирает Мастер; они враждебны ко всем и обычно атакуют ближайших не-демонов.', author_description='Ты не получаешь армию под командованием — ты открываешь дверь и выпускаешь проблему нужного размера. Иногда эта проблема оказывается ближе к врагу, чем к тебе, и на этом строится весь план.', author_comment='Ключевое слово здесь не «призыв», а «демоны». Контроль в комплект не входит.', upcast='Ячейкой 6 или 7 уровня призывается вдвое больше демонов; ячейкой 8 или 9 уровня — втрое больше.', notes='Требуется концентрация. Материальный компонент — кровь гуманоида, убитого за последние 24 часа. Её можно использовать для защитного круга вокруг места сотворения; тогда призванные демоны не могут пересечь круг или атаковать существ внутри него.', casting_time='1 действие' where slug='summon-lesser-demons' and source_kind='official';

update public.spell_catalog set name_ru='Призыв порождения тени', effect_summary='Призываешь теневого духа в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь его облик — Ярость, Отчаяние или Страх — который определяет особое свойство духа. Он действует сразу после тебя, выполняет команды и использует характеристики, зависящие от уровня потраченной ячейки.', author_description='Не просто тень, а тень с настроением. Один вариант лучше давит скоростью, другой пугает, третий предпочитает прямую агрессию.', author_comment='Когда внутренние демоны уже заняты, можно призвать внешнюю тень.', upcast='При использовании ячейки выше 3 её уровень используется в характеристиках теневого духа, увеличивая его хиты, атаку и другие параметры статблока.', notes='Требуется концентрация. Материальный фокус стоимостью 300+ зм не расходуется. Форма выбирается при сотворении и не меняется до окончания заклинания.', casting_time='1 действие' where slug='summon-shadowspawn' and source_kind='official';

update public.spell_catalog set name_ru='Призыв нежити', effect_summary='Призываешь дух нежити в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь форму: Призрачную, Гниющую или Скелетную. Форма меняет способности духа: призрачная связана с страхом и прохождением сквозь препятствия, гниющая — с ядом и парализацией, скелетная — с дальнобойными атаками. Дух действует сразу после тебя и подчиняется командам.', author_description='Три вида нежити в одном заклинании: мобильный призрак, неприятный труп ближнего боя или скелет, который предпочитает стрелять издалека.', author_comment='Некромантия наконец предлагает меню выбора, а не одну стандартную проблему.', upcast='При использовании ячейки выше 3 её уровень используется в характеристиках призванного духа, усиливая его статблок.', notes='Требуется концентрация. Материальный фокус — позолоченный череп стоимостью 300+ зм; он не расходуется. Форма выбирается при сотворении.', casting_time='1 действие' where slug='summon-undead' and source_kind='official';

update public.spell_catalog set name_ru='Гадюка Селунэ', effect_summary='Бонусным действием окружаешь себя призрачной серебряной гадюкой на 1 час без концентрации и получаешь 15 временных хитов. Пока хотя бы один из этих временных хитов остаётся, твоя скорость лазания равна обычной скорости, а действием Магии ты можешь совершать дальнобойную атаку заклинанием по цели в пределах 50 футов. При попадании она получает 1к6 урона силовым полем и становится Отравленной до начала твоего следующего хода; пока она Отравлена этим заклинанием, она также Недееспособна.', author_description='Серебряная змея одновременно служит бронёй, крюком для лазания и очень неприятным дистанционным оружием. Всё это без концентрации, пока держатся выданные временные хиты.', author_comment='Временные хиты обычно защищают. Эти ещё и кусаются на расстоянии.', upcast='За каждый уровень ячейки выше 3 получаешь ещё 5 временных хитов, а урон укуса увеличивается на 1к6.', notes='Заклинание заканчивается раньше, если у тебя не остаётся временных хитов, полученных от него. Материальный компонент — змеиный клык.', casting_time='1 бонусное действие' where slug='sylune-s-viper' and source_kind='official';

update public.spell_catalog set name_ru='Громовой шаг', effect_summary='Телепортируешься в видимое свободное пространство в пределах 90 футов. Сразу после исчезновения раздаётся громовой взрыв: существа в пределах 10 футов от покинутого тобой места делают спасбросок Телосложения, получая 3к10 звукового урона при провале или половину при успехе. Ты можешь забрать с собой одного добровольного союзника своего размера или меньше, находящегося рядом.', author_description='Телепортация, которая не просто выводит тебя из неприятной ситуации, а оставляет этой ситуации прощальный взрыв.', author_comment='Иногда лучший способ уйти красиво — сделать так, чтобы об уходе услышали за триста футов.', upcast='Урон увеличивается на 1к10 за каждый уровень ячейки выше 3.', notes='Гром слышен на расстоянии до 300 футов. Союзник должен находиться в пределах 5 футов от тебя и для него должно быть свободное место рядом с точкой назначения.', casting_time='1 действие' where slug='thunder-step' and source_kind='official';

update public.spell_catalog set name_ru='Приливная волна', effect_summary='Создаёшь волну воды в области до 30 футов длиной, 10 футов шириной и 10 футов высотой в пределах 120 футов. Существа в ней делают спасбросок Ловкости: при провале получают 4к8 дробящего урона и падают ничком, при успехе получают половину урона без падения. Затем вода растекается и исчезает.', author_description='На несколько секунд помещение получает собственное локальное море. Отлично сбивает строй, тушит огонь и очень убедительно объясняет, почему пол теперь мокрый.', author_comment='Водная стихия редко спрашивает, умеют ли цели плавать. Особенно если волна исчезает сразу после удара.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Волна тушит незащищённое пламя в своей области и в пределах 30 футов от неё. После воздействия вода исчезает.', casting_time='1 действие' where slug='tidal-wave' and source_kind='official';

update public.spell_catalog set name_ru='Крошечный слуга', effect_summary='Касаешься одного Крошечного немагического предмета, который никто не носит и не держит, и оживляешь его на 8 часов. Он получает характеристики Крошечного слуги, действует сразу после тебя и выполняет мысленные команды, если находится в пределах 120 футов. Без приказа защищается, но не предпринимает других действий.', author_description='Ложка, сапог, кружка или статуэтка внезапно получают работу. Боевые возможности скромные, зато бытовой потенциал бесконечен.', author_comment='Если предмет достаточно маленький, волшебник рано или поздно попробует нанять его на службу.', upcast='За каждый уровень ячейки выше 3 можно оживить ещё два предмета.', notes='Если управляешь несколькими Крошечными слугами, одной бонусной командой можно отдать одинаковый приказ всем. При 0 хитов предмет возвращается к обычному состоянию.', casting_time='1 минута' where slug='tiny-servant' and source_kind='official';

update public.spell_catalog set name_ru='Стена песка', effect_summary='Создаёшь стену вихрящегося песка в пределах 90 футов на срок до 10 минут с концентрацией. Она может быть до 30 футов длиной, 10 футов высотой и 10 футов толщиной. Стена блокирует линию обзора; существо внутри неё Ослеплено, а каждый фут перемещения через песок требует 3 футов скорости.', author_description='Не останавливает врага физически, зато превращает двадцать шагов в очень долгую прогулку вслепую. Хорошая стена для тех, кто любит контроль без настоящей стены.', author_comment='Песок: дешёвый материал, дорогая скорость передвижения.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Стена не блокирует движение полностью, но пространство внутри крайне трудно преодолевать и через неё нельзя нормально видеть.', casting_time='1 действие' where slug='wall-of-sand' and source_kind='official';

update public.spell_catalog set name_ru='Стена воды', effect_summary='Создаёшь стену воды в пределах 60 футов на срок до 10 минут с концентрацией: либо прямую стену до 30 футов длиной, 10 футов высотой и 1 фута толщиной, либо кольцо до 20 футов в диаметре, 20 футов высотой и 1 фута толщиной. Пространство стены — труднопроходимая местность. Дальнобойные атаки оружием, проходящие через неё, совершаются с помехой, а огненный урон, проходящий через стену, уменьшается вдвое.', author_description='Защитная водяная перегородка: стрелы теряют точность, огонь — энтузиазм, а проходить насквозь просто неудобно.', author_comment='Удивительно много проблем решается, если поставить между собой и проблемой десять футов вертикальной воды.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Заклинание холода, проходящее через стену, замораживает участок минимум 5×5 футов. Замёрзший участок имеет КД 5 и 15 хитов; разрушенный лёд оставляет в стене свободный проход.', casting_time='1 действие' where slug='wall-of-water' and source_kind='official';

commit;